// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { groupsInGraph, removeGraphNodes } from "../../../main/frontend/graph-explorer/graph-operations.ts";

const RDF_TYPE = "http://www.w3.org/1999/02/22-rdf-syntax-ns#type";
const value = '"42"';

test("hiding a resource also drops the values and classes that left with it from named groups", () => {
  const graph = {
    revision: 1,
    nodes: [
      { id: "urn:r", label: "R", kind: "iri" },
      { id: value, label: "42", kind: "literal" },
      { id: "urn:C", label: "C", kind: "iri" },
      { id: "urn:s", label: "S", kind: "iri" },
    ],
    edges: [
      { id: "r-v", source: "urn:r", predicate: "urn:p", label: "p", target: value },
      { id: "r-c", source: "urn:r", predicate: RDF_TYPE, label: "type", target: "urn:C" },
      { id: "r-s", source: "urn:r", predicate: "urn:q", label: "q", target: "urn:s" },
    ],
  };
  const remaining = removeGraphNodes(graph, new Set(["urn:r"]));
  const present = new Set(remaining.nodes.map((node) => node.id));
  assert.deepEqual([...present], ["urn:s"], "the value and the class go with the only resource that used them");
  const groups = [
    { id: "kept", name: "Kept", color: "red", nodeIds: ["urn:r", value, "urn:s"] },
    { id: "emptied", name: "Emptied", color: "blue", nodeIds: [value, "urn:C"] },
  ];
  assert.deepEqual(groupsInGraph(groups, present), [{ id: "kept", name: "Kept", color: "red", nodeIds: ["urn:s"] }]);
  assert.equal(groupsInGraph(groups.slice(0, 0), present).length, 0);
  const unchanged = [{ id: "same", name: "Same", color: "red", nodeIds: ["urn:s"] }];
  assert.equal(groupsInGraph(unchanged, present)[0], unchanged[0], "a group that keeps all its nodes is the same object");
});
